from collections import deque


class ConnectGame:
    def __init__(self, board):
        self.board = [row.strip().split() for row in board.splitlines() if row.strip()]
        self.rows = len(self.board)
        self.cols = len(self.board[0]) if self.rows else 0

    def get_winner(self):
        if self._connects("X", 0, self.cols - 1):
            return "X"
        if self._connects("O", 0, self.rows - 1):
            return "O"
        return ""

    def _connects(self, player, start, end):
        # Player X connects left (col 0) to right (col cols-1).
        # Player O connects top (row 0) to bottom (row rows-1).
        if start == end:
            return any(cell == player for cell in self.board[0])
        start_cells = [
            (0, c) if player == "X" else (r, 0)
            for r in range(self.rows)
            for c in range(self.cols)
            if self.board[r][c] == player and (c == 0 if player == "X" else r == 0)
        ]
        seen = set(start_cells)
        queue = deque(start_cells)
        while queue:
            r, c = queue.popleft()
            if (c == self.cols - 1 if player == "X" else r == self.rows - 1):
                return True
            for dr, dc in ((0, -1), (0, 1), (-1, -1), (-1, 0), (1, 0), (1, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < self.rows and 0 <= nc < self.cols:
                    if (nr, nc) not in seen and self.board[nr][nc] == player:
                        seen.add((nr, nc))
                        queue.append((nr, nc))
        return False

from collections import deque


class ConnectGame:
    def __init__(self, board):
        self.board = [row.strip().split() for row in board.splitlines() if row.strip()]
        self.rows = len(self.board)
        self.cols = len(self.board[0]) if self.rows else 0

    def get_winner(self):
        if self._connects("X"):
            return "X"
        if self._connects("O"):
            return "O"
        return ""

    def _connects(self, player):
        # Player X connects the left edge (col 0) to the right edge (col cols-1).
        # Player O connects the top edge (row 0) to the bottom edge (row rows-1).
        start_edge = (lambda r, c: c == 0) if player == "X" else (lambda r, c: r == 0)
        end_edge = (lambda r, c: c == self.cols - 1) if player == "X" else (lambda r, c: r == self.rows - 1)

        queue = deque(
            (r, c)
            for r in range(self.rows)
            for c in range(self.cols)
            if self.board[r][c] == player and start_edge(r, c)
        )
        seen = set(queue)
        while queue:
            r, c = queue.popleft()
            if end_edge(r, c):
                return True
            for dr, dc in ((0, -1), (0, 1), (-1, -1), (-1, 0), (1, 0), (1, 1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < self.rows and 0 <= nc < self.cols:
                    if (nr, nc) not in seen and self.board[nr][nc] == player:
                        seen.add((nr, nc))
                        queue.append((nr, nc))
        return False
